-- ========== 开始文件: standards_db_v1.0_compliance_evaluation_task.sql ==========
-- MySQL 8.0 — 合规评价任务表（扩展字段与《开发规划》阶段 0 对齐）
-- qb_code 可为 NULL：建任务时尚未确认企标主数据；NULL 不触发指向 enterprise_standard_basic 的外键引用检查。

DROP TABLE IF EXISTS `compliance_evaluation_task`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `compliance_evaluation_task` (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '合规评价任务主键',
  `qb_code` varchar(128) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '企标号；审核确认前可为空',
  `current_step` tinyint unsigned NOT NULL DEFAULT '1' COMMENT '向导步骤 1～6',
  `status` enum('active','failed','archived') COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'active' COMMENT '任务生命周期状态',
  `uploaded_file_path` text COLLATE utf8mb4_unicode_ci COMMENT '企标上传文件存储路径',
  `uploaded_file_name` varchar(512) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '原始文件名',
  `parse_result_json` json DEFAULT NULL COMMENT 'Dify①解析草稿（结构化快照）',
  `indicator_bundle_json` json DEFAULT NULL COMMENT '步骤4编排后的指标聚合（供审4/对比）',
  `compare_result_json` json DEFAULT NULL COMMENT 'Dify③对比结果草稿',
  `dify_run_metadata_json` json DEFAULT NULL COMMENT '各次 Dify run_id、状态等',
  `step4_indicators_confirmed` tinyint(1) NOT NULL DEFAULT '0' COMMENT '审核4是否已通过',
  `step5_compare_confirmed` tinyint(1) NOT NULL DEFAULT '0' COMMENT '审核5是否已通过',
  `created_at` datetime(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6) COMMENT '创建时间',
  `updated_at` datetime(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6) ON UPDATE CURRENT_TIMESTAMP(6) COMMENT '更新时间',
  `created_by` varchar(128) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '创建人标识（与用户体系对齐后可为 user_id）',
  PRIMARY KEY (`id`),
  KEY `idx_compliance_evaluation_task_qb_code` (`qb_code`),
  CONSTRAINT `fk_cet_qb_code` FOREIGN KEY (`qb_code`) REFERENCES `enterprise_standard_basic` (`qb_code`)
    ON UPDATE CASCADE ON DELETE SET NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='合规评价任务表';
