DROP TABLE IF EXISTS `national_standard_extension`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `national_standard_extension` (
  `std_code` varchar(128) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '国标号',
  `responsible_unit` text COLLATE utf8mb4_unicode_ci COMMENT '归口单位/部门',
  `secondary_responsible_unit` text COLLATE utf8mb4_unicode_ci COMMENT '副归口单位',
  `issuing_department` text COLLATE utf8mb4_unicode_ci COMMENT '颁发部门',
  `executing_unit` text COLLATE utf8mb4_unicode_ci COMMENT '执行单位',
  `technical_committee` text COLLATE utf8mb4_unicode_ci COMMENT '技术委员会',
  `governing_department` text COLLATE utf8mb4_unicode_ci COMMENT '主管部门',
  `adoption_status` text COLLATE utf8mb4_unicode_ci COMMENT '采标情况',
  `drafting_unit` text COLLATE utf8mb4_unicode_ci COMMENT '起草单位',
  `drafter` text COLLATE utf8mb4_unicode_ci COMMENT '起草人',
  PRIMARY KEY (`std_code`),
  CONSTRAINT `fk_nse_std_code` FOREIGN KEY (`std_code`) REFERENCES `national_standard_basic` (`std_code`) ON DELETE CASCADE ON UPDATE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='国标基础信息扩展表';
